    @Override public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("nebula",MODE_PRIVATE);secure=new SecureStore(this);parental=new ParentalControl(this,secure,prefs);try{secure.migrateLegacy(prefs);}catch(Exception e){Toast.makeText(this,"Não foi possível migrar o perfil com segurança.",Toast.LENGTH_LONG).show();}if(handleImport(getIntent()))return;JSONObject profile=secure.getProfile();showSplash(()->{String mode=profile.optString("mode","");if(mode.isEmpty())showLogin();else reconnect(profile);});}

    @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);handleImport(intent);}
    @Override public void onConfigurationChanged(Configuration configuration){super.onConfigurationChanged(configuration);if(library==null)return;if("detail".equals(currentScreen)&&currentDetail!=null)showDetails(currentDetail);else if("profiles".equals(currentScreen))showProfiles();else if("home".equals(currentScreen))showHome();else if("search".equals(currentScreen))search();else if("settings".equals(currentScreen))showSettings();else if("live".equals(currentScreen))showSection("live","TV ao vivo");else if("movie".equals(currentScreen))showSection("movie","Filmes");else if("series".equals(currentScreen))showSection("series","Séries");else if("favorites".equals(currentScreen))showSection("favorites","Favoritos");else if("continue".equals(currentScreen))showSection("continue","Continuar assistindo");else showHome();}
    @Override protected void onActivityResult(int requestCode,int resultCode,Intent data){super.onActivityResult(requestCode,resultCode,data);if(requestCode==PICK_LOCAL_PLAYLIST&&resultCode==RESULT_OK&&data!=null&&data.getData()!=null){Uri uri=data.getData();try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}loadLocalPlaylist(uri);}}

    private void showSplash(Runnable next){currentScreen="splash";NebulaBackdropLayout root=new NebulaBackdropLayout(this);ImageView logo=logoImage();logo.setScaleType(ImageView.ScaleType.FIT_CENTER);root.addView(logo,new FrameLayout.LayoutParams(-1,-1));setRoot(root);new Handler(Looper.getMainLooper()).postDelayed(next,1100);}

