    private void showLogin(){NebulaBackdropLayout root=new NebulaBackdropLayout(this);boolean wide=isTv()||getResources().getDisplayMetrics().widthPixels>getResources().getDisplayMetrics().heightPixels;LinearLayout shell=new LinearLayout(this);shell.setOrientation(wide?LinearLayout.HORIZONTAL:LinearLayout.VERTICAL);shell.setPadding(dp(10),dp(10),dp(10),dp(18));LinearLayout visual=new LinearLayout(this);visual.setGravity(Gravity.CENTER);visual.setBackgroundResource(R.drawable.bg_neon_frame);ImageView logo=logoImage();logo.setScaleType(ImageView.ScaleType.FIT_CENTER);visual.addView(logo,new LinearLayout.LayoutParams(-1,-1));LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setGravity(Gravity.CENTER_HORIZONTAL);form.setPadding(dp(24),wide?dp(28):dp(22),dp(24),dp(24));TextView heading=title("Conecte-se",wide?28:25);heading.setGravity(Gravity.START);form.addView(heading,new LinearLayout.LayoutParams(-1,-2));TextView sub=label("Escolha o método de conexão:",14,muted);LinearLayout.LayoutParams subParams=new LinearLayout.LayoutParams(-1,-2);subParams.setMargins(0,dp(6),0,dp(14));form.addView(sub,subParams);Button xt=loginButton("▤   Xtream Codes API   ›");form.addView(xt,loginRow());xt.setOnClickListener(v->showForm("xtream"));Button m3u=loginButton("🔗   Playlist M3U   ›");form.addView(m3u,loginRow());m3u.setOnClickListener(v->showForm("m3u"));Button local=loginButton("▣   Playlist Local   ›");form.addView(local,loginRow());local.setOnClickListener(v->pickLocalPlaylist());Button portal=loginButton("◉   Portal URL   ›");form.addView(portal,loginRow());portal.setOnClickListener(v->showForm("portal"));Button qr=loginButton("▦   Importar por QR Code   ›");form.addView(qr,loginRow());qr.setOnClickListener(v->showQrImport());TextView or=label("————   ou   ————",12,muted);or.setGravity(Gravity.CENTER);LinearLayout.LayoutParams orParams=new LinearLayout.LayoutParams(-1,-2);orParams.setMargins(0,dp(5),0,dp(5));form.addView(or,orParams);Button demo=button("Continuar sem login",false);form.addView(demo,loginRow());demo.setOnClickListener(v->{library=repository.demonstration();try{secure.putProfile("demo","","","","");}catch(Exception ignored){}showProfiles();});TextView legal=label("Utilize somente fontes e conteúdos autorizados.",11,muted);legal.setGravity(Gravity.CENTER);legal.setPadding(0,dp(10),0,0);form.addView(legal,new LinearLayout.LayoutParams(-1,-2));if(wide){root.addView(shell,new FrameLayout.LayoutParams(-1,-1));LinearLayout.LayoutParams visualParams=new LinearLayout.LayoutParams(0,-1,46);visualParams.setMargins(0,0,dp(8),0);shell.addView(visual,visualParams);ScrollView formScroll=new ScrollView(this);formScroll.setFillViewport(true);formScroll.addView(form,new ScrollView.LayoutParams(-1,-2));shell.addView(formScroll,new LinearLayout.LayoutParams(0,-1,54));}else{ScrollView allScroll=new ScrollView(this);allScroll.setFillViewport(true);allScroll.addView(shell,new ScrollView.LayoutParams(-1,-2));root.addView(allScroll,new FrameLayout.LayoutParams(-1,-1));shell.addView(visual,new LinearLayout.LayoutParams(-1,dp(245)));shell.addView(form,new LinearLayout.LayoutParams(-1,-2));}xt.requestFocus();setContentView(root);}

    private void showForm(String mode){
        base();Button back=button("‹ Voltar",false);page.addView(back,new LinearLayout.LayoutParams(dp(130),-2));back.setOnClickListener(v->showLogin());
        ImageView logo=logoImage();logo.setScaleType(ImageView.ScaleType.FIT_CENTER);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(dp(280),dp(158));lp.gravity=Gravity.CENTER_HORIZONTAL;page.addView(logo,lp);
        String heading=mode.equals("xtream")?"Conectar Xtream Codes":mode.equals("portal")?"Conectar Portal URL":"Carregar playlist M3U";TextView h=title(heading,26);h.setGravity(Gravity.CENTER);page.addView(h);
        TextView note=label(mode.equals("portal")?"Portais com resposta M3U são aceitos diretamente. APIs proprietárias precisam ser disponibilizadas e documentadas pelo seu provedor.":"Os dados ficam somente neste dispositivo.",14,muted);note.setGravity(Gravity.CENTER);note.setPadding(0,dp(8),0,dp(16));page.addView(note);
        EditText url=field(mode.equals("xtream")?"Servidor (https://exemplo.com:porta)":"URL da playlist ou portal");page.addView(url,wide());
        EditText user=null,pass=null;if(mode.equals("xtream")){user=field("Usuário");page.addView(user,wide());pass=field("Senha");pass.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);page.addView(pass,wide());}
        EditText epg=field("URL EPG/XMLTV (opcional)");page.addView(epg,wide());
        Button go=button("Conectar",true);page.addView(go,wide());final EditText u=user,p=pass,e=epg;go.setOnClickListener(v->{String value=url.getText().toString().trim();if(value.isEmpty()){url.setError("Informe a URL");return;}connect(mode,value,u==null?"":u.getText().toString(),p==null?"":p.getText().toString(),e.getText().toString());});url.requestFocus();
    }

    private void pickLocalPlaylist(){Intent pick=new Intent(Intent.ACTION_OPEN_DOCUMENT);pick.addCategory(Intent.CATEGORY_OPENABLE);pick.setType("*/*");pick.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"audio/x-mpegurl","application/x-mpegURL","application/vnd.apple.mpegurl","text/plain"});pick.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(pick,PICK_LOCAL_PLAYLIST);}
    private void loadLocalPlaylist(Uri uri){base();ProgressBar pb=new ProgressBar(this);LinearLayout.LayoutParams pp=new LinearLayout.LayoutParams(dp(70),dp(70));pp.gravity=Gravity.CENTER_HORIZONTAL;pp.topMargin=dp(100);page.addView(pb,pp);TextView status=label("Importando playlist local…",16,white);status.setGravity(Gravity.CENTER);page.addView(status);new Thread(()->{try{IptvRepository.Library loaded=repository.loadM3u(getContentResolver().openInputStream(uri),"");runOnUiThread(()->{library=loaded;try{secure.putProfile("local",uri.toString(),"","","");}catch(Exception ignored){}showProfiles();});}catch(Exception e){runOnUiThread(()->new AlertDialog.Builder(this).setTitle("Playlist inválida").setMessage(e.getMessage()).setPositiveButton("Escolher outro arquivo",(d,w)->pickLocalPlaylist()).setNegativeButton("Voltar",(d,w)->showLogin()).show());}}).start();}

    private void reconnect(JSONObject profile){
        String mode=profile.optString("mode","");if("demo".equals(mode)){library=repository.demonstration();showHome();return;}if("local".equals(mode)){loadLocalPlaylist(Uri.parse(profile.optString("url","")));return;}
        connect(mode,profile.optString("url",""),profile.optString("user",""),profile.optString("pass",""),profile.optString("epg",""));
    }

    private void connect(String mode,String url,String user,String pass,String epg){
        base();ProgressBar pb=new ProgressBar(this);LinearLayout.LayoutParams pp=new LinearLayout.LayoutParams(dp(70),dp(70));pp.gravity=Gravity.CENTER_HORIZONTAL;pp.topMargin=dp(100);page.addView(pb,pp);TextView t=label("Conectando à sua fonte autorizada…",16,white);t.setGravity(Gravity.CENTER);t.setPadding(0,dp(15),0,0);page.addView(t);
        new Thread(()->{try{IptvRepository.Library l="xtream".equals(mode)?repository.loadXtream(url,user,pass,epg):repository.loadM3u(url,epg);runOnUiThread(()->{library=l;lastError="";try{secure.putProfile(mode,url,user,pass,epg);}catch(Exception securityError){Toast.makeText(this,"Perfil carregado, mas não foi possível armazená-lo com segurança.",Toast.LENGTH_LONG).show();}showProfiles();});}catch(Exception e){lastError=e.getClass().getSimpleName()+": "+e.getMessage();runOnUiThread(()->{new AlertDialog.Builder(this).setTitle("Não foi possível conectar").setMessage(friendlyConnectionError(e)).setPositiveButton("Revisar dados",(d,w)->showForm(mode)).setNeutralButton("Diagnóstico",(d,w)->shareDiagnostics()).setNegativeButton("Voltar",(d,w)->showLogin()).show();});}}).start();
    }

