    private Button dashboardTile(String glyph,String name,boolean primary,View.OnClickListener click){boolean compact=isCompactLandscape();Button tile=button(glyph+"\n"+name,primary);tile.setTextSize(compact?13:16);tile.setBackgroundResource(primary?R.drawable.bg_selected:R.drawable.bg_card);tile.setOnClickListener(click);tile.setContentDescription(name);tile.setPadding(dp(6),dp(6),dp(6),dp(6));return tile;}
