        if(!compact){Button fav=button(isFavorite(item)?"♥ Favorito":"♡ Favoritar",false);fav.setTextSize(12);fav.setOnClickListener(v->{toggleFavorite(item);fav.setText(isFavorite(item)?"♥ Favorito":"♡ Favoritar");});box.addView(fav,new LinearLayout.LayoutParams(-1,dp(46)));}
